import React, { useState, useEffect } from 'react';
import api from './api';
import AuthModal from './components/AuthModal';
import InteractiveSeating from './components/InteractiveSeating';
import GateSimulator from './components/GateSimulator';
import OrganizerStudio from './components/OrganizerStudio';
import AdminFleetMonitor from './components/AdminFleetMonitor';

function App() {
    const [user, setUser] = useState(() => {
        const saved = localStorage.getItem('tf_user');
        return saved ? JSON.parse(saved) : null;
    });
    const [activeTab, setActiveTab] = useState('catalog');
    const [events, setEvents] = useState([]);
    const [selectedEvent, setSelectedEvent] = useState(null);
    const [tickets, setTickets] = useState([]);
    const [searchQuery, setSearchQuery] = useState('');
    const [selectedCategory, setSelectedCategory] = useState('All');
    const [toasts, setToasts] = useState([]);

    const showToast = (message, type = 'info') => {
        const id = Date.now();
        setToasts(prev => [...prev, { id, message, type }]);
        setTimeout(() => setToasts(prev => prev.filter(t => t.id !== id)), 3600);
    };

    const fetchEvents = async () => {
        try {
            const res = await api.get('/events');
            setEvents(res.data);
        } catch (err) {
            console.error(err);
        }
    };

    const fetchTickets = async () => {
        if (!user) return;
        try {
            const res = await api.get('/tickets/my');
            setTickets(res.data);
        } catch (err) {
            console.error(err);
        }
    };

    useEffect(() => {
        if (user) {
            fetchEvents();
            fetchTickets();
        }
    }, [user]);

    const handleLogout = () => {
        localStorage.removeItem('tf_token');
        localStorage.removeItem('tf_user');
        setUser(null);
        setSelectedEvent(null);
        setActiveTab('catalog');
    };

    if (!user) {
        return (
            <>
                <AuthModal onAuthSuccess={(u) => setUser(u)} showToast={showToast} />
                <ToastContainer toasts={toasts} />
            </>
        );
    }

    const filteredEvents = events.filter(ev => {
        const matchesCat = selectedCategory === 'All' || ev.category === selectedCategory;
        const matchesQuery = ev.title.toLowerCase().includes(searchQuery.toLowerCase()) || ev.venue.toLowerCase().includes(searchQuery.toLowerCase());
        return matchesCat && matchesQuery;
    });

    return (
        <div className="bg-slate-950 text-slate-100 min-h-screen flex flex-col">
            {/* TOP NAVIGATION BAR */}
            <header className="sticky top-0 z-40 bg-slate-900/90 backdrop-blur-md border-b border-slate-800/80">
                <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-3 flex flex-wrap items-center justify-between gap-3">
                    <div className="flex items-center gap-3 cursor-pointer" onClick={() => { setSelectedEvent(null); setActiveTab('catalog'); }}>
                        <div className="w-10 h-10 rounded-xl bg-gradient-to-br from-cyan-400 to-emerald-500 flex items-center justify-center shadow-lg shadow-cyan-500/20 text-slate-950 font-extrabold text-lg">
                            🎟️
                        </div>
                        <div>
                            <div className="flex items-center gap-2">
                                <span className="font-extrabold text-lg tracking-tight text-white">TicketFlow</span>
                                <span className="text-[11px] font-mono font-bold px-2 py-0.5 rounded-full bg-cyan-500/15 text-cyan-400 border border-cyan-500/30">IoT EDGE v2.4</span>
                            </div>
                            <p className="text-xs text-slate-400 hidden sm:block">Smart Ticketing &amp; Autonomous Venue Access</p>
                        </div>
                    </div>

                    <nav className="flex flex-wrap items-center gap-1.5 bg-slate-950/90 p-1.5 rounded-xl border border-slate-800">
                        <button onClick={() => { setSelectedEvent(null); setActiveTab('catalog'); }} className={`px-3 py-2 rounded-lg text-xs sm:text-sm font-semibold transition ${activeTab === 'catalog' ? 'bg-cyan-500 text-slate-950 shadow-md' : 'text-slate-300 hover:bg-slate-800'}`}>
                            🎟️ Event Catalog
                        </button>
                        <button onClick={() => setActiveTab('tickets')} className={`flex items-center gap-2 px-3 py-2 rounded-lg text-xs sm:text-sm font-semibold transition ${activeTab === 'tickets' ? 'bg-cyan-500 text-slate-950 shadow-md' : 'text-slate-300 hover:bg-slate-800'}`}>
                            <span>📡 My Tickets &amp; IoT Gate</span>
                            <span className="text-[11px] font-mono font-bold px-1.5 py-0.5 rounded-full bg-emerald-500/20 text-emerald-400 border border-emerald-500/30">{tickets.length}</span>
                        </button>
                        {(user.role === 'ORGANIZER' || user.role === 'ADMIN') && (
                            <button onClick={() => setActiveTab('organizer')} className={`px-3 py-2 rounded-lg text-xs sm:text-sm font-semibold transition ${activeTab === 'organizer' ? 'bg-cyan-500 text-slate-950 shadow-md' : 'text-slate-300 hover:bg-slate-800'}`}>
                                📊 Organizer Studio
                            </button>
                        )}
                        {user.role === 'ADMIN' && (
                            <button onClick={() => setActiveTab('admin')} className={`px-3 py-2 rounded-lg text-xs sm:text-sm font-semibold transition ${activeTab === 'admin' ? 'bg-cyan-500 text-slate-950 shadow-md' : 'text-slate-300 hover:bg-slate-800'}`}>
                                🛡️ System &amp; IoT Fleet
                            </button>
                        )}
                    </nav>

                    {/* User Profile & Logout */}
                    <div className="flex items-center gap-3">
                        <div className="text-right hidden sm:block">
                            <p className="text-xs font-bold text-white">{user.fullName}</p>
                            <p className="text-[10px] font-mono text-cyan-400">{user.role}</p>
                        </div>
                        <button onClick={handleLogout} className="px-3 py-1.5 rounded-lg bg-slate-800 hover:bg-rose-500/20 hover:text-rose-300 border border-slate-700 text-xs font-semibold transition">
                            Sign Out
                        </button>
                    </div>
                </div>
            </header>

            <ToastContainer toasts={toasts} />

            <main className="flex-1 max-w-7xl w-full mx-auto px-4 sm:px-6 lg:px-8 py-6">
                {activeTab === 'catalog' && !selectedEvent && (
                    <div className="space-y-6">
                        <div className="rounded-2xl bg-gradient-to-r from-slate-900 via-slate-850 to-slate-900 border border-slate-800 p-6 sm:p-8 flex flex-col lg:flex-row lg:items-center justify-between gap-6">
                            <div className="max-w-2xl space-y-2">
                                <div className="inline-flex items-center gap-2 px-3 py-1 rounded-full bg-emerald-500/10 border border-emerald-500/30 text-emerald-400 text-xs font-medium">
                                    <span className="w-2 h-2 rounded-full bg-emerald-400 animate-ping"></span>
                                    Zero-Queue Autonomous Gate Entry Enabled
                                </div>
                                <h1 className="text-2xl sm:text-3xl font-extrabold tracking-tight text-white">
                                    Discover Live Events. <span className="text-transparent bg-clip-text bg-gradient-to-r from-cyan-400 to-emerald-400">Walk Straight Through the Gate.</span>
                                </h1>
                                <p className="text-sm text-slate-400">Reserve exact seats with MySQL pessimistic locking, receive cryptographic QR tickets, and scan at our turnstiles.</p>
                            </div>

                            <div className="w-full lg:w-96 space-y-3">
                                <input type="text" value={searchQuery} onChange={(e) => setSearchQuery(e.target.value)} placeholder="Search artist, venue, or city..." className="w-full px-4 py-2.5 rounded-xl bg-slate-950 border border-slate-700/80 text-sm text-white focus:outline-none focus:border-cyan-500" />
                                <div className="flex flex-wrap gap-1.5">
                                    {['All', 'Concerts', 'Festivals', 'Theater', 'Comedy'].map(cat => (
                                        <button key={cat} onClick={() => setSelectedCategory(cat)} className={`px-3 py-1.5 rounded-lg text-xs font-semibold ${selectedCategory === cat ? 'bg-cyan-500 text-slate-950' : 'bg-slate-800 text-slate-300 hover:bg-slate-700'}`}>
                                            {cat}
                                        </button>
                                    ))}
                                </div>
                            </div>
                        </div>

                        <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                            {filteredEvents.map(ev => (
                                <div key={ev.id} className="group bg-slate-900 border border-slate-800 hover:border-cyan-500/50 rounded-2xl overflow-hidden transition-all flex flex-col justify-between shadow-lg">
                                    <div className={`p-6 bg-gradient-to-br ${ev.gradient} border-b border-slate-800/80`}>
                                        <div className="flex items-center justify-between gap-2 mb-3">
                                            <span className="px-2.5 py-1 rounded-full text-xs font-semibold bg-slate-950/70 text-cyan-300 border border-cyan-500/30">{ev.category}</span>
                                            <span className="px-2.5 py-1 rounded-full text-xs font-mono font-semibold bg-emerald-500/20 text-emerald-300 border border-emerald-500/30">{ev.totalCapacity - ev.soldCount} seats left</span>
                                        </div>
                                        <h3 className="text-xl font-extrabold text-white group-hover:text-cyan-300 transition">{ev.title}</h3>
                                        <p className="text-sm text-slate-300 mt-1">📍 {ev.venue}</p>
                                        <p className="text-xs font-mono text-slate-400 mt-1">🗓️ {ev.date}</p>
                                    </div>

                                    <div className="p-5 flex items-center justify-between gap-4 bg-slate-900">
                                        <div>
                                            <p className="text-[11px] uppercase tracking-wider text-slate-400 font-semibold">Tickets From</p>
                                            <p className="text-lg font-extrabold font-mono text-white">{ev.gaPrice} <span className="text-xs font-normal text-slate-400">RON</span></p>
                                        </div>
                                        <button onClick={() => setSelectedEvent(ev)} className="px-5 py-2.5 rounded-xl bg-cyan-500 hover:bg-cyan-400 text-slate-950 font-bold text-sm transition shadow-md shadow-cyan-500/20">
                                            Select Seats →
                                        </button>
                                    </div>
                                </div>
                            ))}
                        </div>
                    </div>
                )}

                {activeTab === 'catalog' && selectedEvent && (
                    <InteractiveSeating
                        event={selectedEvent}
                        user={user}
                        onBack={() => { setSelectedEvent(null); fetchEvents(); }}
                        onCheckoutSuccess={() => {
                            setSelectedEvent(null);
                            fetchEvents();
                            fetchTickets();
                            setActiveTab('tickets');
                        }}
                        showToast={showToast}
                    />
                )}

                {activeTab === 'tickets' && (
                    <GateSimulator
                        tickets={tickets}
                        onRefreshTickets={fetchTickets}
                        onBuyMore={() => { setSelectedEvent(null); setActiveTab('catalog'); }}
                        showToast={showToast}
                    />
                )}

                {activeTab === 'organizer' && (
                    <OrganizerStudio events={events} onEventCreated={fetchEvents} showToast={showToast} />
                )}

                {activeTab === 'admin' && (
                    <AdminFleetMonitor showToast={showToast} />
                )}
            </main>
        </div>
    );
}

const ToastContainer = ({ toasts }) => (
    <div className="fixed bottom-5 right-5 z-50 flex flex-col gap-2 max-w-sm w-full pointer-events-none px-4 sm:px-0">
        {toasts.map(t => {
            const colors = {
                success: 'bg-slate-900 border-emerald-500/60 text-emerald-200',
                warning: 'bg-slate-900 border-amber-500/60 text-amber-200',
                error: 'bg-slate-900 border-rose-500/60 text-rose-200',
                info: 'bg-slate-900 border-cyan-500/60 text-cyan-200'
            };
            const icons = { success: '✅', warning: '⚠️', error: '🛑', info: 'ℹ️' };
            return (
                <div key={t.id} className={`pointer-events-auto flex items-start gap-3 p-3.5 rounded-xl border shadow-2xl text-xs font-medium ${colors[t.type]}`}>
                    <span>{icons[t.type]}</span>
                    <p>{t.message}</p>
                </div>
            );
        })}
    </div>
);

export default App;
